67.     /// Instantiates a kernel frame.
68.     ///
69.     /// # Parameters
70.     ///
71.     /// - `base`: Frame address.
72.     ///
73.     /// # Returns
74.     ///
75.     /// Upon success, a kernel frame is returned. Upon failure, an error is returned instead.
76.     ///
77.     // Dependency contract: wrapping a frame goes through `mm::virt::identity_map_page`, which
78.     // is outside the verification scope of `mm::phys`. On success the returned handle owns the
79.     // same physical frame that was passed in.
80.     #[verus_spec(result =>
81.         requires
82.             base.inv(),
83.         ensures
84.             match result {
