90.         // Ensure the frame is identity-mapped in the kernel address space so that
91.         // Deref/DerefMut can safely access it. This lazily installs a page
92.         // table entry if needed (page tables come from a BSS pool, so no recursive frame
93.         // allocation occurs).
94.         let phys_addr: PageAligned<PhysicalAddress> =
95.             PageAligned::from_raw_value(base.into_raw_value()).map_err(|e| {
96.                 error!("frame base is not page-aligned: {e:?}");
97.                 e
98.             })?;
99.         crate::mm::virt::identity_map_page(phys_addr).map_err(|e| {
100.             error!("failed to identity-map frame: {:?}", e);
